mapper.sql:
select max(HIS_NO) HIS_NO, WORKFLOW_ID from SYS_DATA_PROCESS_MARK
PAGE_ID = #{pageId}
PAGE_ID in
#{item}
group by WORKFLOW_ID

mapper.select:
select pm.STATUS status,
pm.BUSINESS_DATA_PK1 allData,
pm.WORKFLOW_ID workflowId
from SYS_DATA_PROCESS_MARK pm
inner join () tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


		pm.status in ('A','U','P')


		and pm.PAGE_ID = #{pageId}


		and pm.PAGE_ID in

			#{item}



		and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


		and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


		and pm.BUSINESS_DATA_PK3 = #{businessDataPk3}


		and pm.BUSINESS_DATA_PK4 = #{businessDataPk4}


		and pm.BUSINESS_DATA_PK5 = #{businessDataPk5}


		and pm.BUSINESS_DATA_PK6 = #{businessDataPk6}


		and pm.BUSINESS_DATA_PK7 = #{businessDataPk7}


		and pm.BUSINESS_DATA_PK8 = #{businessDataPk8}


		and pm.BUSINESS_DATA_PK9 = #{businessDataPk9}


		and pm.BUSINESS_DATA_PK10 = #{businessDataPk10}


		and pm.WORKFLOW_ID != #{workflowId}



order by pm.create_time desc

SELECT
COUNT(1)
FROM
TRD_FEE_CONFIG m
LEFT JOIN TRD_FEE_CONFIG_DETAIL T ON m.SEQ_NO = T.SEQ_NO
WHERE
m.PS = #{ps,jdbcType=VARCHAR}
AND
m.TRADE_TYPE = #{tradeType,jdbcType=VARCHAR}
AND
m.FEE_TYPE = #{feeType,jdbcType=VARCHAR}
AND
m.TRADE_MARKET = #{TRADE_PLACE_01,jdbcType=VARCHAR}
AND
m.EFF_DATE = to_date(case #{effDate,jdbcType=VARCHAR} when '' then null else #{effDate,jdbcType=VARCHAR} end ,'yyyy-mm-dd HH24:mi:ss')
and T.IS_MLTI = #{isMlti,jdbcType=VARCHAR}

	AND m.TERM_TYPE = #{termType,jdbcType=VARCHAR}


	and  BATCH_SEQ <> #{batchSeq}


	and m.REGIST_ORG = #{registOrg}

SELECT
m.BATCH_SEQ batchSeq
FROM
TRD_FEE_CONFIG m
LEFT JOIN TRD_FEE_CONFIG_DETAIL T ON m.SEQ_NO = T.SEQ_NO
WHERE
m.PS = #{ps,jdbcType=VARCHAR}
AND
m.TRADE_TYPE = #{tradeType,jdbcType=VARCHAR}
AND
m.FEE_TYPE = #{feeType,jdbcType=VARCHAR}
AND
m.TRADE_MARKET = #{TRADE_PLACE_01,jdbcType=VARCHAR}
AND
m.EFF_DATE = to_date(#{effDate,jdbcType=VARCHAR},'yyyy-mm-dd HH24:mi:ss')
and T.IS_MLTI = #{isMlti,jdbcType=VARCHAR}

	AND m.TERM_TYPE = #{termType,jdbcType=VARCHAR}


	and  BATCH_SEQ <> #{batchSeq}


	and m.REGIST_ORG = #{registOrg}
